"""demo.py — 快路径影子演示(不碰模型/麦克风/执行)

  python -m opencode_fastpath.demo
"""
from __future__ import annotations

import os
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))

from opencode_fastpath.fastpath import FastPath  # noqa: E402


def main():
    tmp = Path(tempfile.mkdtemp(prefix="ocfp_demo_"))
    fp = FastPath(table_path=tmp / "table.json", mode="shadow", log_dir=tmp / "logs")
    fp.install("open_url", "B站", ["打开B站"], additive=False)  # 演示用基表
    cases = [
        ("打开B站", {"intent": "open_url", "conf": 0.97, "src": "rule"}),
        ("打开B战", {"intent": "unknown", "conf": 0.21, "src": "embed"}),
        ("打开记事板", {"intent": "unknown", "conf": 0.33, "src": "embed"}),
        ("跑一下回归", {"intent": "unknown", "conf": 0.12, "src": "embed"}),
    ]
    print("=== 影子模式: 快路径只记录, 不改写原逻辑结果 ===")
    for text, model in cases:
        r = fp.route(text)
        fp.observe(text, model)
        print(f"  「{text}」  key={r['key']}")
        print(f"     快路径: {r['decision']:<4} {r['intent'] or ''} {r['arg'] or ''}"
              f"  (additive={r['additive']}, blocked={r['blocked']})   {r['latency_us']}µs")
        note = "可救回(rescue)" if r["decision"] == "hit" and model["intent"] == "unknown" else "一致/无需"
        print(f"     原逻辑: {model['intent']} (conf {model['conf']})  → {note}")

    print("\n=== 教师学习: 把规则漏掉的同音说法入库(additive=True) ===")
    fp.install("launch_app", "记事本", ["打开记事板", "开一下记事板"], additive=True,
               markers={"source": "teacher", "note": "demo"})
    fp.install("dsh_run", "", ["跑一下回归"], additive=True, markers={"source": "teacher"})
    for text in ["打开记事板", "跑一下回归"]:
        r = fp.route(text)
        print(f"  「{text}」 → {r['decision']} {r['intent']}  add={r['additive']}  blocked={r['blocked']}")

    print("\n=== live 语义: 只接管 additive 且非破坏性 ===")
    fp.mode = "live"
    for text in ["打开B站", "打开记事板", "跑一下回归"]:
        r = fp.route(text)
        would = r["decision"] == "hit" and r["additive"] and not r["blocked"]
        print(f"  「{text}」 → {'接管(0模型)' if would else '回退原逻辑'}")

    st = fp.stats()
    print(f"\n表: 条目 {st['entries']}  全串行 {st['full']}  前缀行 {st['prefix']}  "
          f"实占 {st['bytes']}B  载入 {st['load']}")
    print(f"日志: {fp.log_dir}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
